local applied = {}

local function requestShards()
  for _, shard in ipairs(shards) do
    if not HasStreamedTextureDictLoaded(shard) then RequestStreamedTextureDict(shard, false) end
  end
end

local function applyAvailable(force)
  for _, shard in ipairs(shards) do
    if HasStreamedTextureDictLoaded(shard) and (force or not applied[shard]) then
      for txd, entries in pairs(replacements) do
        for _, entry in ipairs(entries) do
          if entry[2] == shard then
            RemoveReplaceTexture(txd, entry[1])
            AddReplaceTexture(txd, entry[1], entry[2], entry[3])
          end
        end
      end
      applied[shard] = true
    end
  end
end

local function applyInitialPass()
  requestShards()
  local deadline = GetGameTimer() + 60000
  while GetGameTimer() < deadline do
    applyAvailable(false)
    local complete = true
    for _, shard in ipairs(shards) do if not applied[shard] then complete = false; break end end
    if complete then break end
    requestShards()
    Wait(250)
  end
  local loaded = 0
  for _, shard in ipairs(shards) do if applied[shard] then loaded = loaded + 1 end end
  print(('[apocalypse-gas-stations] active shards: %d/%d'):format(loaded, #shards))
end

CreateThread(applyInitialPass)
AddEventHandler('playerSpawned', function()
  CreateThread(function() Wait(2500); requestShards(); Wait(500); applyAvailable(true) end)
end)
AddEventHandler('onResourceStop', function(resource)
  if resource ~= GetCurrentResourceName() then return end
  for txd, entries in pairs(replacements) do for _, entry in ipairs(entries) do RemoveReplaceTexture(txd, entry[1]) end end
end)
